// ---- Smooth audio clock -------------------------------------------------
// <audio>.currentTime advances in coarse steps and reports the *scheduled* position, not what the player hears.
// We interpolate between ticks with performance.now(), ease toward the real clock (never going backwards),
// and subtract the device output latency so notes line up with the sound that reaches the ears.
const clk={ct:-1,pn:0,est:0,last:0,skipVis:null};
let latCtx=null;
function primeLatency(){try{if(!latCtx){const AC=window.AudioContext||window.webkitAudioContext;if(AC)latCtx=new AC({latencyHint:'interactive'});}latCtx?.resume?.();}catch{}}
function outputLatencyMs(){try{return latCtx?clamp(((latCtx.outputLatency||0)+(latCtx.baseLatency||0))*1000,0,250):0;}catch{return 0;}}
function resetClock(){clk.ct=-1;clk.est=0;clk.last=0;}
function songMs(){
  const ct=audio.currentTime*1000,pn=performance.now();
  if(lead.on){const rem=state.paused?lead.rem:Math.max(0,lead.end-pn);return -rem-outputLatencyMs()+state.settings.offset+beatOff(state.chart?.chartId);}
  if(audio.paused||audio.ended){clk.ct=ct;clk.pn=pn;clk.est=ct;clk.last=pn;}
  else{
    if(ct!==clk.ct){clk.ct=ct;clk.pn=pn;}
    const target=clk.ct+(pn-clk.pn)*audio.playbackRate,dt=clk.last?pn-clk.last:0;clk.last=pn;
    if(!clk.est||Math.abs(target-clk.est)>90)clk.est=target;
    else{clk.est+=dt*audio.playbackRate;clk.est+=(target-clk.est)*.12;}
  }
  const ms=clk.est-outputLatencyMs()+state.settings.offset+beatOff(state.chart?.chartId);
  if(state.screen==='game')updateSkip(clk.est);
  return ms;
}
function updateSkip(ms){const first=state.chart?.notes?.[0]?.timeMs||0,vis=first>6000&&ms<first-3500&&!state.paused;if(vis===clk.skipVis)return;clk.skipVis=vis;const b=document.getElementById('osu-skip');if(b)b.classList.toggle('show',vis);}
function skipIntro(){const first=state.chart?.notes?.[0]?.timeMs||0;if(first>6000)audio.currentTime=Math.max(0,first-2500)/1000;}
const lead={on:false,end:0,rem:0,timer:0,tick:0};
