function attachAudioPulse(media){
  if(pulseAnalyserByAudio.has(media))return pulseAnalyserByAudio.get(media);
  try{primeLatency();if(!latCtx||latCtx.state!=='running')return null;
    const source=latCtx.createMediaElementSource(media),analyser=latCtx.createAnalyser();analyser.fftSize=1024;analyser.smoothingTimeConstant=.3;source.connect(analyser);analyser.connect(latCtx.destination);
    const node={analyser,data:new Uint8Array(analyser.frequencyBinCount),prev:new Float32Array(analyser.frequencyBinCount),avg:.02,lastBeat:0};pulseAnalyserByAudio.set(media,node);return node;}catch{return null;}
}
function spawnPulseRing(){
  if(state.settings.reducedMotion||document.hidden)return;
  const host=document.querySelector('.lz-logo-gap')||document.querySelector('.rf-splash-logo-wrap');if(!host)return;
  if(host.querySelectorAll('.rf-pulse-ring').length>5)return;
  const ring=document.createElement('i');ring.className='rf-pulse-ring';ring.addEventListener('animationend',()=>ring.remove());host.append(ring);
}
// Beat detector: low/mid spectral flux against a running average. Drives --rf-beat (fast attack, exponential decay)
// so the logo and icons kick on the actual drum hits instead of tracking raw loudness.
function startAudioPulse(){
  if(visualizerRaf)return;
  let last=performance.now();
  const root=document.documentElement;let lastBeatVar=-1,lastLevelVar=-1;
  const tick=now=>{visualizerRaf=0;const dt=Math.min(64,Math.max(1,now-last));last=now;
    if(latCtx&&latCtx.state==='suspended')latCtx.resume().catch(()=>{});
    const media=state.screen==='game'&&!audio.paused?audio:!previewAudio.paused?previewAudio:!bgmAudio.paused?bgmAudio:null;let level=0;
    pulseBeat*=Math.exp(-dt/150);
    if(media&&!state.settings.reducedMotion){const node=pulseAnalyserByAudio.get(media)||attachAudioPulse(media);
      if(node){node.analyser.getByteFrequencyData(node.data);const d=node.data,pv=node.prev;let flux=0,low=0;
        for(let i=1;i<8;i++){const v=d[i]/255,diff=v-pv[i];if(diff>0)flux+=diff;pv[i]=v;low+=v;}
        low/=7;level=Math.min(1,low*1.15);
        // Kick/bass onsets only (47–330 Hz), adaptive threshold, 230 ms refractory period => one pulse per drum hit, not per hi-hat.
        const thr=Math.max(.3,node.avg*2.1);
        if(flux>thr&&low>.2&&now-node.lastBeat>230){node.lastBeat=now;pulseBeat=Math.max(pulseBeat,Math.min(1,.65+flux*.3));spawnPulseRing();}
        node.avg=node.avg*.9+flux*.1;}}
    if(pulseBeat<.01)pulseBeat=0;
    const b=Math.round(pulseBeat*100)/100,l=Math.round(level*100)/100;
    if(b!==lastBeatVar){lastBeatVar=b;root.style.setProperty('--rf-beat',String(b));}
    if(l!==lastLevelVar){lastLevelVar=l;root.style.setProperty('--rf-audio-level',String(l));}
    if(media||pulseBeat>0)visualizerRaf=requestAnimationFrame(tick);};
  visualizerRaf=requestAnimationFrame(tick);
}
