function escapeHtml(value='') { return String(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); }
function rfLogoSvg(size=28){return `<svg viewBox="0 0 64 64" width="${size}" height="${size}" fill="none" aria-hidden="true" focusable="false"><path d="M32 3 57 17.5v29L32 61 7 46.5v-29L32 3Z" fill="currentColor" fill-opacity=".16"/><path d="M32 3 57 17.5v29L32 61 7 46.5v-29L32 3Z" stroke="currentColor" stroke-width="3.2" stroke-linejoin="round"/><rect x="17" y="30" width="6" height="14" rx="3" fill="currentColor"/><rect x="26" y="20" width="6" height="24" rx="3" fill="currentColor"/><rect x="35" y="25" width="6" height="19" rx="3" fill="currentColor"/><rect x="44" y="34" width="6" height="10" rx="3" fill="currentColor"/></svg>`;}
function brandMark(size=28,extra=''){return `<span class="rf-brand-mark ${extra}" style="--brand-size:${size}px" aria-hidden="true">${rfLogoSvg(size)}</span>`;}
function formatDuration(ms) { if(!ms)return '—';const s=Math.floor(ms/1000);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`; }
