function saveSettings() { try { localStorage.setItem('rf-settings',JSON.stringify(state.settings)); } catch { /* file:// and privacy-restricted contexts may disable localStorage */ } const shell=document.querySelector('.app-shell');if(shell){if(state.settings.theme)shell.setAttribute('data-theme',state.settings.theme);shell.setAttribute('data-skin',state.settings.skin||'midnight');} }
async function openDb(){if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{if(!('indexedDB'in window)){reject(Error('IndexedDB unavailable'));return;}const req=indexedDB.open(STORE.db,STORE.version);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('projects'))db.createObjectStore('projects',{keyPath:'id'});if(!db.objectStoreNames.contains('results'))db.createObjectStore('results',{keyPath:'key'});if(!db.objectStoreNames.contains('plays'))db.createObjectStore('plays',{keyPath:'id'});if(!db.objectStoreNames.contains('bgmTracks'))db.createObjectStore('bgmTracks',{keyPath:'id'});if(!db.objectStoreNames.contains('playerProfiles'))db.createObjectStore('playerProfiles',{keyPath:'id'});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('Database open failed'));});return dbPromise;}
function withTimeout(promise,ms,message){let timer;return Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error(message||'Storage operation timed out')),ms);})]).finally(()=>clearTimeout(timer));}
async function dbRequest(store,mode,method,value){return withTimeout((async()=>{const db=await openDb();return new Promise((resolve,reject)=>{let tx;try{tx=db.transaction(store,mode);const os=tx.objectStore(store),req=value===undefined?os[method]():os[method](value);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error||Error('Storage request failed'));tx.onerror=()=>reject(tx.error||Error('Storage transaction failed'));}catch(error){reject(error);}});})(),4500,`Local database access timed out (${store}).`);}
async function loadProjects(){try{return (await dbRequest('projects','readonly','getAll')).sort((a,b)=>b.updatedAt-a.updatedAt);}catch{try{return JSON.parse(localStorage.getItem('rf-projects')||'[]');}catch{return [];}}}
async function saveProject(project,notify=false){const updated={...project,updatedAt:Date.now()};state.project=updated;state.projects=[updated,...state.projects.filter(p=>p.id!==updated.id)].sort((a,b)=>b.updatedAt-a.updatedAt);try{await dbRequest('projects','readwrite','put',updated);if(notify)showToast('Project saved locally');}catch{const slim=state.projects.map(({audioBlob,imageBlob,videoBlob,...p})=>p);try{localStorage.setItem('rf-projects',JSON.stringify(slim));if(notify)showToast('Chart metadata saved; binary media could not fit browser storage.');}catch{showToast('Storage is full. Export the chart JSON as a backup.');}}}
function showConfirmModal(title,body,label,fn){
  closeDeleteModal();
  const host=document.createElement('div');host.id='rf-delete-modal';host.className='rf-modal-host';host.setAttribute('role','dialog');host.setAttribute('aria-modal','true');
  host.innerHTML=`<div class="rf-modal"><div class="rf-modal-ico">${icon('trash',20)}</div><h3>${escapeHtml(title)}</h3><p>${escapeHtml(body)}</p><div class="rf-modal-actions"><button type="button" class="btn btn-quiet" data-rf="cancel">Cancel</button><button type="button" class="btn btn-danger" data-rf="confirm">${escapeHtml(label)}</button></div></div>`;
  host.addEventListener('click',e=>{const b=e.target.closest('[data-rf]');if(e.target===host||b?.dataset.rf==='cancel'){closeDeleteModal();return;}if(b?.dataset.rf==='confirm'){closeDeleteModal();void fn();}});
  document.body.append(host);host.querySelector('[data-rf="cancel"]')?.focus();
}
