function clearRenderLoops(){if(gameRaf){cancelAnimationFrame(gameRaf);gameRaf=0;}if(editorRaf){cancelAnimationFrame(editorRaf);editorRaf=0;}if(gameObserver){gameObserver.disconnect();gameObserver=null;}if(editorObserver){editorObserver.disconnect();editorObserver=null;}}
function renderFullscreenGame(){
  clearRenderLoops();
  // During play, replace the entire app root with the game surface. No studio chrome or toast overlays.
  document.querySelector('.toast')?.remove();
  state.toast='';clearTimeout(toastTimer);
  root.innerHTML=`<div class="app-shell theme-${escapeHtml(state.settings.theme)} rhythm-fullscreen-shell" data-skin="${escapeHtml(state.settings.skin||'midnight')}">${gamePage()}</div>`;
  if(state.chart)mountGame();
}
function requestGameFullscreen(){
  // Never lock orientation: portrait and landscape are both supported by the responsive playfield.
  try{window.screen?.orientation?.unlock?.();}catch{}
  // CSS keeps the game full-viewport where the Fullscreen API is unavailable (notably some mobile browsers).
  if(document.fullscreenElement||!root.requestFullscreen)return;
  try{const result=root.requestFullscreen({navigationUI:'hide'});if(result&&typeof result.catch==='function')result.catch(()=>{});}catch{}
}
function exitBrowserFullscreen(){
  if(document.fullscreenElement&&document.exitFullscreen){try{const result=document.exitFullscreen();if(result&&typeof result.catch==='function')result.catch(()=>{});}catch{}}
}
function resumeGameLoop(){if(game?.drawLoop&&!gameRaf&&state.screen==='game'&&!state.paused&&(!audio.paused||lead.on)&&!game.finished)gameRaf=requestAnimationFrame(game.drawLoop);}
