  state.result={score:game.score,scoreVersion:SCORE_V2_VERSION,scoreBreakdown:game.scoreBreakdown,accuracy,combo:game.combo,maxCombo:game.maxCombo,judgements:{...game.counts},grade:gradeForScoreV2(accuracy),chartId:state.chart.chartId,difficulty:state.chart.metadata.difficulty,completedAt:Date.now(),holdsCompleted:game.holdsCompleted||0,holdBonus:0,performance:performanceAnalysis};
