function onClick(event){const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(action!=='select-song'&&action!=='play-project'&&action!=='touch-lane')unlockMenuAudio();switch(action){case 'navigate':route(target.dataset.screen);break;case 'gen-adv':genAdv=!genAdv;render();break;case 'set-gen-mode':if(Object.hasOwn(MODES,target.dataset.mode)&&target.dataset.mode!=='custom'){genMode=target.dataset.mode;render();}break;case 'lz-tab':lzTab=target.dataset.tab;render();break;case 'scroll-to':document.getElementById(target.dataset.target)?.scrollIntoView({behavior:'smooth',block:'start'});break;case 'random-song':{const ps=state.projects;if(ps.length){const picked=ps[Math.floor(Math.random()*ps.length)];selId=picked.id;previewProject(picked.id);state.searchQuery='';render();}break;}case 'loader-back':clearLoader();exitBrowserFullscreen();state.screen='library';render();break;case 'loader-start':launchLoader();break;case 'loader-adjust':loaderAdjust(false);break;case 'loader-adjust-global':loaderAdjust(true);break;case 'loader-toggle':changeSetting(target.dataset.setting,!state.settings[target.dataset.setting],false);renderLoader(true);break;case 'select-song':selId=target.dataset.id;previewProject(selId);render();break;case 'select-diff':changeSetting('difficulty',target.dataset.difficulty,false);render();break;case 'gen-project':openProject(target.dataset.id);state.screen='generator';render();break;case 'skip-intro':skipIntro();break;case 'demo':startDemo();break;case 'choose-audio':if(event.target.type!=='file')chooseAudio();break;case 'set-speed':changeSetting('speed',Number(target.dataset.value));break;case 'add-bgm':{const input=document.createElement('input');input.type='file';input.accept='audio/*,.mp3,.wav,.ogg,.flac,.m4a';input.multiple=true;input.onchange=()=>{if(input.files?.length)void addBgmFiles(input.files);};input.click();break;}case 'remove-bgm':void removeBgmTrack(target.dataset.id);break;case 'choose-background':{const input=document.createElement('input');input.type='file';input.accept='image/*,video/*';input.onchange=()=>setBackground(input.files?.[0]);input.click();break;}case 'clear-background':if(state.backgroundUrl)URL.revokeObjectURL(state.backgroundUrl);state.backgroundUrl='';state.backgroundType='';backgroundMedia=null;if(backgroundVideo){backgroundVideo.pause();backgroundVideo.remove();backgroundVideo=null;}render();break;case 'open-mobile':state.mobileNavOpen=true;render();break;case 'close-mobile':state.mobileNavOpen=false;render();break;case 'help':showToast('Import a local track, generate a chart, then play or edit it. Press D F J K on desktop.');break;case 'engine-status':showToast('Audio engine ready · Web Audio API · Local processing');break;case 'dismiss-toast':state.toast='';renderToast();break;case 'open-project':openProject(target.dataset.id);break;case 'play-project':playProject(target.dataset.id);break;case 'delete-project':showDeleteModal(target.dataset.id);break;case 'reset-data':showConfirmModal('Reset data?','Scores, play history, your skill profile and per-song timing offsets will be erased. Songs and settings stay.','Reset data',resetUserData);break;case 'delete-all-songs':if(state.projects.length)showConfirmModal('Delete all songs?',`All ${state.projects.length} songs, their charts and scores will be removed from this browser. This cannot be undone.`,'Delete all',deleteAllSongs);break;case 'clear-filters':state.diffFilter='all';state.searchQuery='';render();break;case 'cancel-delete':state.confirmDelete=null;render();break;case 'confirm-delete':void deleteProject(state.confirmDelete);state.confirmDelete=null;break;case 'analyze':void analyzeAndGenerate();break;case 'cancel-analysis':analysisCancelled=true;break;case 'difficulty':selectDifficulty(target.dataset.difficulty);break;case 'regenerate':regenerateSelected();break;case 'play-chart':startGame(state.chart);break;case 'open-editor':if(state.chart){audio.pause();exitBrowserFullscreen();state.paused=false;state.screen='editor';editorUndo=[];editorRedo=[];editorSelectedId=null;render();}else showToast('Generate a chart first.');break;case 'preview-chart':startGame(state.chart);break;case 'save-chart':void saveCurrentChart();break;case 'export-chart':exportChart();break;case 'toggle-validation':state.validationOpen=!state.validationOpen;render();break;case 'undo':undoEdit();break;case 'redo':redoEdit();break;case 'zoom-in':editorZoom=Math.min(4,Math.round(editorZoom*1.25*100)/100);render();break;case 'zoom-out':editorZoom=Math.max(.6,Math.round(editorZoom/1.25*100)/100);render();break;case 'editor-tool':editorTool=target.dataset.tool==='hold'?'hold':'tap';render();break;case 'convert-hold':{const n=selectedNote();if(n&&n.type!=='hold'){const beat=60000/(state.chart.metadata.bpm||120),nextSame=state.chart.notes.filter(x=>x.lane===n.lane&&x.timeMs>n.timeMs).sort((a,b)=>a.timeMs-b.timeMs)[0],end=Math.min(state.chart.metadata.audioDurationMs-1,n.timeMs+beat*2,nextSame?nextSame.timeMs-40:Infinity);if(end-n.timeMs<beat*.5){showToast('There is not enough free space for a hold tail.');break;}commitChart({...state.chart,notes:state.chart.notes.map(x=>x.id===n.id?{...x,type:'hold',endTimeMs:Math.round(end)}:x)},'Converted tap to hold');render();}break;}case 'hold-duration':{const n=selectedNote();if(n?.type==='hold'){const beat=60000/(state.chart.metadata.bpm||120),delta=Number(target.dataset.delta)*beat,nextSame=state.chart.notes.filter(x=>x.lane===n.lane&&x.timeMs>n.timeMs).sort((a,b)=>a.timeMs-b.timeMs)[0],end=Math.min(state.chart.metadata.audioDurationMs-1,nextSame?nextSame.timeMs-40:Infinity,Math.max(n.timeMs+beat*.5,n.endTimeMs+delta));if(end-n.timeMs<beat*.5){showToast('A hold note must be at least half a beat long.');break;}commitChart({...state.chart,notes:state.chart.notes.map(x=>x.id===n.id?{...x,endTimeMs:Math.round(end)}:x)},'Hold duration updated');render();}break;}case 'delete-note':{const n=selectedNote();if(n){commitChart({...state.chart,notes:state.chart.notes.filter(x=>x.id!==n.id)},'Note deleted');editorSelectedId=null;render();}break;}case 'nudge':nudgeSelected(Number(target.dataset.delta)*beatMs(state.chart.metadata.bpm||120,editorSnap));break;case 'nudge-lane':nudgeSelected(0,Number(target.dataset.delta));break;case 'reset-settings':state.settings={...DEFAULT_SETTINGS};saveSettings();render();showToast('Settings reset to defaults.');break;case 'toggle-setting':{const key=target.dataset.setting;changeSetting(key,!state.settings[key]);if(key==='bgmEnabled'){if(state.settings.bgmEnabled)resumeMenuBgm();else pauseMenuBgm();}break;}case 'capture-key':state.captureKey=Number(target.dataset.lane);render();showToast('Press any letter or number key to assign it.');break;case 'adjust-offset':changeSetting('offset',state.settings.offset+Number(target.dataset.delta));break;case 'clear-background':if(state.backgroundUrl)URL.revokeObjectURL(state.backgroundUrl);state.backgroundUrl='';state.backgroundType='';backgroundMedia=null;render();break;case 'pause-game':pauseGame();break;case 'resume-game':resumeGame();break;case 'restart-game':restartGame();break;case 'resume-audio':audio.play().then(()=>{state.autoplayBlocked=false;render();resumeGameLoop();}).catch(()=>{});break;case 'exit-game':clearLead();audio.pause();exitBrowserFullscreen();state.paused=false;state.screen='home';render();resumeMenuMusic();break;case 'toggle-mute':audio.muted=!audio.muted;target.innerHTML=`${icon('wave',15)} ${audio.muted?'Muted':'Audio'}`;break;case 'touch-lane':{const lane=Number(target.dataset.lane);if(state.screen==='game'&&game&&!state.paused){const now=songMs(),n=state.chart.notes.filter(n=>n.lane===lane&&!game.judged.has(n.id)).sort((a,b)=>Math.abs(a.timeMs-now)-Math.abs(b.timeMs-now))[0];if(n&&Math.abs(n.timeMs-now)<=220)registerHit(lane,now-n.timeMs,n);}break;}case 'toggle-difficulty':break;}}
function onChange(event){const el=event.target;if(el.matches('#song-difficulty-filter')){state.diffFilter=el.value||'all';if(state.diffFilter!=='all')changeSetting('difficulty',state.diffFilter,false);render();return;}if(el.matches('[data-field="genMode"]')){genMode=el.value;return;}if(el.matches('[data-field="seed"]'))state.seed=Number(el.value)||0;else if(el.matches('[data-field="bpmOverride"]'))state.bpmOverride=el.value;else if(el.matches('[data-field="offsetOverride"]'))state.offsetOverride=el.value;else if(el.matches('[data-field="editor-snap"]'))editorSnap=el.value;else if(el.matches('[data-field="show-waveform"]')){editorShowWaveform=el.checked;if(state.screen==='editor')render();}else if(el.matches('[data-field="chart-bpm"]')){const bpm=Number(el.value);if(Number.isFinite(bpm)&&bpm>=30&&bpm<=300){commitChart({...state.chart,metadata:{...state.chart.metadata,bpm}},`BPM set to ${bpm}`);render();}}else if(el.matches('[data-field="import-chart"]')){if(el.files?.[0])void importChart(el.files[0]);el.value='';}else if(el.matches('[data-setting]')){const key=el.dataset.setting;changeSetting(key,el.value);}}
function onInput(event){const el=event.target;if(el.matches('#song-search')){state.searchQuery=el.value;const query=el.value.trim().toLowerCase();let visible=0;document.querySelectorAll('.lz-card[data-search]').forEach(card=>{const diff=document.getElementById('song-difficulty-filter')?.value||'all';const show=(!query||card.dataset.search.includes(query))&&(diff==='all'||card.dataset.difficulties.split(',').includes(diff));card.hidden=!show;if(show)visible++;});const count=document.getElementById('song-count');if(count)count.textContent=`${visible} song${visible===1?'':'s'}`;const empty=document.getElementById('song-search-empty');if(empty)empty.hidden=visible>0;return;}if(el.matches('[data-field="beat-offset"]')){const id=state.loader?.chart.chartId;setBeatOff(id,Number(el.value));const o=document.getElementById('beat-off-value');if(o)o.textContent=fmtMs(beatOff(id));return;}if(el.matches('[data-field="density"]')){state.density=Number(el.value);const out=document.getElementById('density-value');if(out)out.textContent=`${state.density.toFixed(2)}×`;}else if(el.matches('[data-field="confidence"]')){state.confidence=Number(el.value);const out=document.getElementById('confidence-value');if(out)out.textContent=state.confidence.toFixed(2);}else if(el.matches('[data-setting]')){const key=el.dataset.setting;if(el.type==='range'){changeSetting(key,Number(el.value),false);const out=document.getElementById(`setting-${key}-value`);if(out)out.textContent=fmtSetting(key,Number(el.value));const num=document.getElementById(`setting-${key}-num`);if(num)num.value=el.value;}}}
function onGlobalKeyDown(event){if(state.captureKey!==undefined&&state.captureKey!==null){event.preventDefault();const key=event.key.toLowerCase();if(key.length===1&&!state.settings.keys.some((x,i)=>x===key&&i!==state.captureKey)){const keys=[...state.settings.keys];keys[state.captureKey]=key;state.settings.keys=keys;state.captureKey=null;saveSettings();render();}else if(key==='escape'){state.captureKey=null;render();}return;}const target=event.target;if(state.screen==='editor'&&!(target instanceof HTMLInputElement)&&!(target instanceof HTMLSelectElement)&&!(target instanceof HTMLTextAreaElement)){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='z'){event.preventDefault();event.shiftKey?redoEdit():undoEdit();return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='y'){event.preventDefault();redoEdit();return;}if(event.key==='Delete'||event.key==='Backspace'){if(selectedNote()){event.preventDefault();const n=selectedNote();commitChart({...state.chart,notes:state.chart.notes.filter(x=>x.id!==n.id)},'Note deleted');editorSelectedId=null;render();}return;}if(event.key==='ArrowLeft'){event.preventDefault();nudgeSelected(-beatMs(state.chart.metadata.bpm||120,editorSnap));return;}if(event.key==='ArrowRight'){event.preventDefault();nudgeSelected(beatMs(state.chart.metadata.bpm||120,editorSnap));return;}if(event.key==='ArrowUp'){event.preventDefault();nudgeSelected(0,-1);return;}if(event.key==='ArrowDown'){event.preventDefault();nudgeSelected(0,1);return;}}
if(state.screen==='game'&&game&&!state.paused&&!event.repeat){if(event.key==='Escape'){event.preventDefault();pauseGame();return;}if(event.code==='Space'){event.preventDefault();pauseGame();return;}const key=event.key.toLowerCase(),lane=state.settings.keys.indexOf(key);if(lane>=0){event.preventDefault();game.pressed.add(key);const now=songMs(),near=findNearestNote(lane,now,220);if(near)registerHit(lane,now-near.timeMs,near);}}}
window.addEventListener('keyup',event=>{if(game){const key=event.key.toLowerCase();game.pressed.delete(key);const lane=state.settings.keys.indexOf(key);if(lane>=0)releaseHoldsForLane(lane);}});
window.addEventListener('blur',()=>{if(game){const lanes=new Set([...game.activeHolds.values()].map(h=>h.lane));game.pressed.clear();game.pointerLanes.clear();for(const lane of lanes)releaseHoldsForLane(lane);}});

async function init(){
  // Paint the application shell immediately. A file:// browser may block or delay
  // IndexedDB; startup must never leave #root empty while storage is opening.
  render();
  const loaded=await Promise.allSettled([loadProjects(),loadResults(),loadLocalPlays(),loadBgmTracks(),loadPlayerProfile()]);
  state.projects=loaded[0].status==='fulfilled'&&Array.isArray(loaded[0].value)?loaded[0].value:[];
  state.bestResults=loaded[1].status==='fulfilled'&&Array.isArray(loaded[1].value)?loaded[1].value:[];
  state.localPlays=loaded[2].status==='fulfilled'&&Array.isArray(loaded[2].value)?loaded[2].value:[];
  state.bgmTracks=loaded[3].status==='fulfilled'&&Array.isArray(loaded[3].value)?loaded[3].value:[{id:'rf-theme-default',name:'Rhythm Forge Theme',src:AUDIO_DEMO,builtIn:true}];
  state.playerProfile=loaded[4].status==='fulfilled'?loaded[4].value:null;
  render();
  rfReadyResolve();
  if(bgmUnlocked)resumeMenuMusic();
}
showSplash();
void init().catch(error=>{
  rfReadyResolve();
  console.error('Rhythm Forge startup recovery:',error);
  state.projects=state.projects||[];state.bestResults=state.bestResults||[];state.localPlays=state.localPlays||[];
  try{render();showToast('Some local data could not be loaded. The app is running with temporary storage.');}
  catch(renderError){console.error('Rhythm Forge render failure:',renderError);root.innerHTML='<main style="min-height:100vh;display:grid;place-content:center;padding:32px;background:#090b11;color:#f6f7fb;font:16px system-ui;text-align:center"><h1>Rhythm Forge</h1><p>The app could not finish starting.</p><p style="color:#aab2c5">Close this tab and reopen the standalone HTML in a recent version of Chrome, Edge, or Safari.</p></main>';}
});

setInterval(()=>{const c=document.querySelector('.lz-clock');if(!c)return;c.textContent=new Date().toLocaleTimeString('en-GB');const r=document.querySelector('.lz-run');if(r){const t=Math.floor((Date.now()-LZ_START)/1000),p=n=>String(n).padStart(2,'0');r.textContent=`running ${p(Math.floor(t/3600))}:${p(Math.floor(t/60)%60)}:${p(t%60)}`;}},1000);

// Main menu: clicking the logo slides the button strip in/out; Enter/Space also toggles it.
document.addEventListener('click',e=>{const logo=e.target.closest('.lz-logo');if(!logo)return;const m=logo.closest('.lz-menu');if(!m)return;const now=performance.now();if(now-lastLogoToggleAt<500)return;lastLogoToggleAt=now;
  if(m.classList.contains('open')){navigate_to_library();}else{m.classList.add('open');}});
function navigate_to_library(){route('library');}


// ---- Start screen (osu!-style): one click unlocks browser audio so music works after every reload.
const SILENT_WAV='data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEARKwAAIhYAQACABAAZGF0YQAAAAA=';
function showSplash(){
  if(document.getElementById('rf-splash'))return;
  const el=document.createElement('div');el.id='rf-splash';el.setAttribute('role','dialog');el.setAttribute('aria-label','Rhythm Forge start screen');
  el.innerHTML=`<div class="rf-splash-bg"></div>${Array.from({length:16},(_,i)=>`<i class="rf-tri" style="--x:${(i*37)%100}%;--s:${28+(i*23)%60}px;--d:${9+(i*7)%9}s;--dl:-${(i*5)%11}s"></i>`).join('')}<div class="rf-splash-logo-wrap"><button type="button" class="rf-splash-logo" id="rf-splash-logo" aria-label="Start Rhythm Forge">${rfLogoSvg(110)}<span class="rf-wm">rhythm<b>forge</b></span></button></div><p class="rf-splash-hint" id="rf-splash-hint">Loading…</p><p class="rf-splash-ver">v0.1.0 · Rhythm Forge is in Alpha. More features are coming soon!</p>`;
  document.body.append(el);
  let started=false;
  const start=async e=>{
    if(started)return;started=true;e?.preventDefault?.();document.removeEventListener('keydown',onKey,true);
    bgmUnlocked=true;
    try{primeLatency();latCtx?.resume?.();}catch{}
    // Unlock the gameplay <audio> element inside this user gesture so later programmatic play() is allowed (iOS/Safari).
    if(!audioUnlocked)try{audioUnlocked=true;const keep=audio.src;audio.muted=true;audio.src=SILENT_WAV;void audio.play().then(()=>{audio.pause();audio.muted=false;audio.src=keep;}).catch(()=>{audio.muted=false;audio.src=keep;});}catch{}
    if(state.bgmTracks.length)resumeMenuMusic();
    el.classList.add('out');
    setTimeout(()=>el.remove(),650);
    if(!state.bgmTracks.length){await Promise.race([rfReady,new Promise(r=>setTimeout(r,2500))]);resumeMenuMusic();}
  };
  const onKey=e=>{if(e.key==='Enter'||e.key===' '){start(e);}};
  el.querySelector('#rf-splash-logo').addEventListener('click',start);
  document.addEventListener('keydown',onKey,true);
  rfReady.then(()=>{const h=document.getElementById('rf-splash-hint');if(h)h.textContent='Click the logo to start';el.classList.add('ready');});
}
